import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as d,c as s,f as r,q as a,D as l,Q as o,g as i}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const k=JSON.parse('{"title":"模型模型上下文与命中缓存","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/基础认知/模型模型上下文与命中缓存.md","filePath":"column/AIFuture/基础认知/模型模型上下文与命中缓存.md","lastUpdated":1786931132000}'),p={name:"column/AIFuture/基础认知/模型模型上下文与命中缓存.md"};function h(c,t,u,g,b,m){const e=d("ArticleMetadata");return r(),s("div",null,[t[0]||(t[0]=a("h1",{id:"模型模型上下文与命中缓存",tabindex:"-1"},[i("模型模型上下文与命中缓存 "),a("a",{class:"header-anchor",href:"#模型模型上下文与命中缓存","aria-label":'Permalink to "模型模型上下文与命中缓存"'},"​")],-1)),l(e),t[1]||(t[1]=o(`<nav class="table-of-contents"><ul><li><a href="#一、模型上下文-大模型的-工作记忆">一、模型上下文：大模型的“工作记忆”</a><ul><li><a href="#_2026年8月主流模型上下文长度">2026年8月主流模型上下文长度</a></li><li><a href="#为什么上下文长度很重要">为什么上下文长度很重要？</a></li></ul></li><li><a href="#二、命中缓存-为什么同样的输入-费用和速度会差很多">二、命中缓存：为什么同样的输入，费用和速度会差很多</a><ul><li><a href="#主流厂商的实现差异-2026年">主流厂商的实现差异（2026年）</a></li></ul></li><li><a href="#三、上下文与缓存的关系">三、上下文与缓存的关系</a></li><li><a href="#四、实际使用中的关键问题">四、实际使用中的关键问题</a></li></ul></nav><p><strong>模型上下文与命中缓存：理解大模型真正的成本和效率</strong></p><p>在使用大模型时，很多人最关心两件事： 一是“它一次能处理多长的内容”，二是“为什么有时候费用突然变便宜、响应变快”。</p><p>这两个问题分别对应两个核心概念——<strong>模型上下文（Context Window）</strong> 和 <strong>命中缓存（Prompt Caching / Cache Hit）</strong>。它们既独立，又深度关联。理解清楚这两者，能帮你更好地控制成本、提升速度，并设计更高效的对话与 Agent 系统。</p><h2 id="一、模型上下文-大模型的-工作记忆" tabindex="-1">一、模型上下文：大模型的“工作记忆” <a class="header-anchor" href="#一、模型上下文-大模型的-工作记忆" aria-label="Permalink to &quot;一、模型上下文：大模型的“工作记忆”&quot;">​</a></h2><p>大语言模型在生成回复时，并不是只看你最新发的那一句话，而是会把以下内容一起纳入考虑：</p><ul><li>系统提示词（System Prompt）</li><li>历史对话记录</li><li>你当前输入的内容</li><li>附带的文档、代码、工具定义等</li></ul><p>这些内容加在一起，就是模型的<strong>上下文</strong>。 上下文有上限，这个上限称为<strong>上下文窗口（Context Window）</strong>，单位是 token。</p><p>超过这个长度后，最早的内容会被截断或挤掉，模型就“看不见”了。可以把它理解为模型的工作记忆：容量越大，一次能处理的信息就越多。</p><h3 id="_2026年8月主流模型上下文长度" tabindex="-1">2026年8月主流模型上下文长度 <a class="header-anchor" href="#_2026年8月主流模型上下文长度" aria-label="Permalink to &quot;2026年8月主流模型上下文长度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型/系列</th><th>厂商</th><th>最大上下文长度</th><th>备注</th></tr></thead><tbody><tr><td>Qwen Long / 部分特殊模型</td><td>阿里</td><td>10M（1000万）</td><td>目前广告最长之一</td></tr><tr><td>Llama 4 Scout</td><td>Meta</td><td>10M（1000万）</td><td>开源权重，实际有效使用远低于标称</td></tr><tr><td>Grok 系列</td><td>xAI</td><td>2M（200万）</td><td>多个变体支持</td></tr><tr><td>Claude 系列</td><td>Anthropic</td><td>1M（100万）</td><td>长上下文质量较高</td></tr><tr><td>GPT-5.x 系列</td><td>OpenAI</td><td>约1M～1.05M</td><td>多数旗舰支持</td></tr><tr><td>Gemini 3.x 系列</td><td>Google</td><td>1M</td><td>普遍为1M</td></tr><tr><td>DeepSeek V4、Qwen3.8 Max、Kimi K3 等</td><td>多家</td><td>1M</td><td>国产与开源模型已跟进</td></tr></tbody></table><p><strong>1M tokens 大概是什么概念？</strong> 约75万～100万中文字，或1500～2000页普通文档，或一个中大型代码仓库。</p><p>需要特别注意：<strong>广告长度 ≠ 有效长度</strong>。很多模型在接近上限时会出现明显的“中间遗忘”现象，真正稳定好用的有效长度通常只有标称值的50%～80%。</p><h3 id="为什么上下文长度很重要" tabindex="-1">为什么上下文长度很重要？ <a class="header-anchor" href="#为什么上下文长度很重要" aria-label="Permalink to &quot;为什么上下文长度很重要？&quot;">​</a></h3><ol><li><p><strong>长文档处理能力</strong> 直接把整份合同、研究报告、代码库丢进去进行总结、问答、对比分析，而不需要先做复杂的切片和检索。</p></li><li><p><strong>多轮对话的连贯性</strong> 上下文越长，模型能记住的对话历史就越多，越不容易“失忆”。</p></li><li><p><strong>复杂 Agent 任务</strong> 智能体在执行多步骤任务时，往往会积累大量中间结果和工具调用记录。长上下文能显著提升任务完成率。</p></li><li><p><strong>减少对 RAG 的依赖</strong> 在很多场景下，直接把相关材料全部塞进上下文，比“检索 + 生成”的流程更简单、更准确。</p></li></ol><h2 id="二、命中缓存-为什么同样的输入-费用和速度会差很多" tabindex="-1">二、命中缓存：为什么同样的输入，费用和速度会差很多 <a class="header-anchor" href="#二、命中缓存-为什么同样的输入-费用和速度会差很多" aria-label="Permalink to &quot;二、命中缓存：为什么同样的输入，费用和速度会差很多&quot;">​</a></h2><p>大模型处理请求时，会先对输入的 prompt 做一次“预计算”（Prefill），生成内部的注意力状态（KV Cache）。这个过程在输入很长时，既耗时又昂贵。</p><p><strong>命中缓存（Cache Hit）</strong> 的意思是：如果下一次请求的<strong>开头部分（前缀）和之前完全一样</strong>，服务端可以直接复用之前算好的结果，而不用重新计算。</p><ul><li>命中缓存 → 跳过重复计算 → 更便宜、更快</li><li>未命中（Cache Miss） → 从头完整计算 → 按原价计费，延迟更高</li></ul><p>它缓存的不是最终答案，而是模型处理 prompt 时产生的中间计算结果。因此，即使命中缓存，模型每次仍然会生成新的回复。</p><h3 id="主流厂商的实现差异-2026年" tabindex="-1">主流厂商的实现差异（2026年） <a class="header-anchor" href="#主流厂商的实现差异-2026年" aria-label="Permalink to &quot;主流厂商的实现差异（2026年）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>厂商</th><th>开启方式</th><th>最低长度</th><th>缓存读取价格（大约）</th><th>缓存写入</th><th>有效期（TTL）</th></tr></thead><tbody><tr><td>OpenAI</td><td>自动</td><td>≥1024 tokens</td><td>约10%～50%原价</td><td>通常免费</td><td>5～10分钟</td></tr><tr><td>Anthropic (Claude)</td><td>需手动标记 <code>cache_control</code></td><td>1024～4096 tokens</td><td>约10%原价（省90%）</td><td>1.25～2倍原价</td><td>默认5分钟，可选1小时</td></tr><tr><td>Google (Gemini)</td><td>显式创建 Context Cache</td><td>较高</td><td>较低，另收存储费</td><td>有存储费用</td><td>可自定义</td></tr><tr><td>DeepSeek</td><td>自动</td><td>自动</td><td>约10%原价</td><td>通常无额外费用</td><td>十几到几十分钟</td></tr></tbody></table><p>核心规则只有一条：<strong>必须从 prompt 的最开头开始完全一致，才能命中</strong>。改一个标点、换一行顺序，都可能导致缓存失效。</p><h2 id="三、上下文与缓存的关系" tabindex="-1">三、上下文与缓存的关系 <a class="header-anchor" href="#三、上下文与缓存的关系" aria-label="Permalink to &quot;三、上下文与缓存的关系&quot;">​</a></h2><p>长上下文让缓存变得更有价值。</p><p>当系统指令、工具定义、背景材料动辄几千甚至上万 tokens 时，如果每次都重新计算，成本和延迟会迅速累积。缓存正是为了解决这个问题而生——把那些<strong>稳定不变、反复出现</strong>的长前缀结果复用起来。</p><p>反过来，如果你每次请求的内容都完全不同、没有任何固定前缀，那么即使模型支持超长上下文，也几乎享受不到缓存带来的优惠。</p><p>两者结合后的实际效果是：</p><ul><li>长上下文决定了你一次能塞进多少信息</li><li>缓存决定了这些信息在重复使用时，要不要每次都重新付费计算</li></ul><h2 id="四、实际使用中的关键问题" tabindex="-1">四、实际使用中的关键问题 <a class="header-anchor" href="#四、实际使用中的关键问题" aria-label="Permalink to &quot;四、实际使用中的关键问题&quot;">​</a></h2><p><strong>1. 每次问题都不一样，还能命中缓存吗？</strong></p><p>可以。 只要前面有一段足够长、完全相同的固定内容（系统指令、工具、背景材料），即使后面的用户问题每次都不同，固定前缀依然可以命中缓存。</p><p>推荐结构：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[固定部分]  ← 可命中缓存</span></span>
<span class="line"><span>  系统指令</span></span>
<span class="line"><span>  工具定义</span></span>
<span class="line"><span>  背景知识 / 文档</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[变化部分]  ← 每次不同</span></span>
<span class="line"><span>  当前这一次的问题</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>2. 第一次给了稳定内容，后来改了系统指令，还能命中原来的缓存吗？</strong></p><p>不能。 系统指令一旦有任何改动，前缀就不再一致，原来的缓存立即失效。需要重新计算新的系统指令，并在之后保持新内容稳定，才能开始命中<strong>新的缓存</strong>。</p><p><strong>3. 如何提高命中率？</strong></p><ul><li>把稳定内容固定放在最前面</li><li>不要在系统提示词里加时间戳、随机ID等动态信息</li><li>尽量少改系统指令和工具定义</li><li>观察 API 返回的用量字段（如 <code>cached_tokens</code>、<code>cache_read_input_tokens</code>），确认真正命中了多少</li></ul>`,38))])}const x=n(p,[["render",h]]);export{k as __pageData,x as default};
